import { type PetPortalDisplay } from "@/server/branches/branches.type";
/**
 * ما تسمح الأكاديمية بعرضه في تطبيق وليّ الأمر.
 *
 * ── لماذا الفرع الرئيسي ─────────────────────────────────────────────────
 *
 * الإعدادات القابلة للنموّ في هذا النظام تعيش في `Branch.settings` (نمط
 * `branchSettingsSchema`: مفاتيح جديدة بلا هجرات)، بينما تطبيق وليّ الأمر **على مستوى
 * الأكاديمية**: سجلّ الطفل يجمع أحداثًا من كل الفروع. فلا بدّ من قاعدة تحكيم واحدة،
 * وقاعدتنا: **إعدادات الفرع الرئيسي (PRIMARY) تحكم التطبيق كلّه.**
 *
 * البديل — أن يتبع كلُّ حدثٍ إعداداتِ فرعه — يبدو أدقّ لكنه يُنتج سجلًّا لا يُفهم:
 * تطعيمٌ ظاهر وتطعيمٌ مخفيّ في الشاشة نفسها لأنهما أُعطيا في فرعين، ووليّ الأمر لا يعرف
 * أصلًا أن للأكاديمية فروعًا.
 *
 * أكاديمية بلا فرع رئيسي (أو لم تلمس الإعدادات) تحصل على الافتراضيات — وكلّها `true`،
 * فالسلوك القائم لا يتغيّر إلا بقرار.
 */
export declare function portalDisplay(clinicId: string): Promise<PetPortalDisplay>;
